INSERT INTO cms.article (id, slug, title_en, title_ar, excerpt_en, excerpt_ar, body_en, body_ar, body_html_en, body_html_ar, cover_url, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, category, tags, author_name, status, publish_at, featured, created_at, updated_at) VALUES ('art-1', 'saffron-table-2026-outlook', 'Saffron Table 2026 GCC Market Outlook & Benchmarks', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — مائدة الزعفران', 'Key operational benchmarks, real metrics, and 2026 guidance from Saffron Table in Adliya.', 'أبرز المعايير التشغيلية والأرقام الموثقة وإرشادات 2026 من مائدة الزعفران في Adliya.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Contemporary Bahraini kitchen and gourmet pantry crafting daily fresh dishes, specialty spice blends, and corporate catering. Focusing on Corporate Buffet Catering (50 Guests), our teams help Gulf enterprises scale reliably."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"مطبخ بحريني معاصر ومتجر منتجات غذائية يقدم أطباقاً طازجة يومياً وخلطات توابل فاخرة وضيافة للشركات. من خلال خدمة ضيافة بوفيه للشركات (50 ضيفاً) نساعد المؤسسات على النمو المستدام."}]}]}'::jsonb, '<p>Contemporary Bahraini kitchen and gourmet pantry crafting daily fresh dishes, specialty spice blends, and corporate catering.</p><p>Focusing on <strong>Corporate Buffet Catering (50 Guests)</strong>, our Adliya specialists help Gulf organizations standardize turnaround times and audit transparency.</p>', '<p>مطبخ بحريني معاصر ومتجر منتجات غذائية يقدم أطباقاً طازجة يومياً وخلطات توابل فاخرة وضيافة للشركات.</p><p>من خلال خدمة <strong>ضيافة بوفيه للشركات (50 ضيفاً)</strong>، يعمل فريقنا في Adliya على توحيد سرعة التسليم ووضوح التدقيق.</p>', '/api/files/media/banners/banner-01.png', 'Saffron Table 2026 GCC Market Outlook & Benchmarks | Saffron Table', 'توقعات أسواق الخليج ومعايير الأداء لعام 2026 — مائدة الزعفران | مائدة الزعفران', 'Executive guide by Saffron Table covering Corporate Buffet Catering (50 Guests) benchmarks in Bahrain.', 'دليل تنفيذي من مائدة الزعفران حول معايير ضيافة بوفيه للشركات (50 ضيفاً) في البحرين.', 'Insights', '{"food","insights","Adliya","2026"}'::text[], 'Hana Yousef', 'published', now() - interval '6 days', true, now() - interval '6 days', now()) ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('faq-1', 'How quickly can Saffron Table initiate a Corporate Buffet Catering (50 Guests) engagement?', 'كم يستغرق بدء تنفيذ خدمة ضيافة بوفيه للشركات (50 ضيفاً) لدى مائدة الزعفران؟', 'Discovery and kickoff begin within 48 hours of quotation sign-off, with a dedicated lead assigned in Adliya.', 'يبدأ التخطيط والتنفيذ خلال 48 ساعة من اعتماد عرض السعر مع تعيين مدير حساب مخصص في Adliya.', 'services', true, 1, now() - interval '45 days') ON CONFLICT (id) DO NOTHING;
