INSERT INTO cms.website_content (id, draft, published, previous, revision, published_at, updated_at) VALUES ('main', '{"company":{"nameEn":"Saffron Table Hospitality W.L.L.","nameAr":"مائدة الزعفران للضيافة ذ.م.م","shortEn":"Saffron Table","shortAr":"مائدة الزعفران","taglineEn":"Artisanal Gulf Kitchen, Pantry & Event Catering","taglineAr":"مطبخ خليجي حرفي ومنتجات غذائية وضيافة مناسبات","aboutEn":"Contemporary Bahraini kitchen and gourmet pantry crafting daily fresh dishes, specialty spice blends, and corporate catering.","aboutAr":"مطبخ بحريني معاصر ومتجر منتجات غذائية يقدم أطباقاً طازجة يومياً وخلطات توابل فاخرة وضيافة للشركات."},"hero":{"titleEn":"Saffron Table — Artisanal Gulf Kitchen, Pantry & Event Catering","titleAr":"مائدة الزعفران — مطبخ خليجي حرفي ومنتجات غذائية وضيافة مناسبات","ctaLabelEn":"Explore Saffron Table","ctaLabelAr":"استكشف مائدة الزعفران"},"featuredServices":[{"code":"SVC-CAT","en":"Corporate Buffet Catering (50 Guests)","ar":"ضيافة بوفيه للشركات (50 ضيفاً)","rate":480},{"code":"SVC-CHEF","en":"Private Chef Tasting Menu","ar":"قائمة تذوق مع شيف خاص","rate":320},{"code":"FOD-COR","en":"Executive Boardroom Catering Packages","ar":"خدمات ضيافة اجتماعات مجالس الإدارة","rate":260},{"code":"FOD-LIV","en":"Live Saj, Karak & Dessert Station","ar":"محطة طهي حي للصاج والكرك والحلويات","rate":340}]}'::jsonb, '{"company":{"nameEn":"Saffron Table Hospitality W.L.L.","nameAr":"مائدة الزعفران للضيافة ذ.م.م","shortEn":"Saffron Table","shortAr":"مائدة الزعفران","taglineEn":"Artisanal Gulf Kitchen, Pantry & Event Catering","taglineAr":"مطبخ خليجي حرفي ومنتجات غذائية وضيافة مناسبات","aboutEn":"Contemporary Bahraini kitchen and gourmet pantry crafting daily fresh dishes, specialty spice blends, and corporate catering.","aboutAr":"مطبخ بحريني معاصر ومتجر منتجات غذائية يقدم أطباقاً طازجة يومياً وخلطات توابل فاخرة وضيافة للشركات."},"hero":{"titleEn":"Saffron Table — Artisanal Gulf Kitchen, Pantry & Event Catering","titleAr":"مائدة الزعفران — مطبخ خليجي حرفي ومنتجات غذ