INSERT INTO cms.review (id, author_en, author_ar, company_en, company_ar, quote_en, quote_ar, rating, is_approved, sort_order, year, created_at) VALUES ('149efe3b-2bfc-417e-a182-282489564f06', 'Eng. Salman Al-Moayyed', 'م. سلمان المؤيد', 'Almoayyed Contracting Group W.L.L.', 'مجموعة المؤيد للمقاولات ذ.م.م', 'Saffron Table consistently delivers on complex Bahrain commercial schedules with transparent VAT documentation and responsive bilingual account leads.', 'تلتزم مائدة الزعفران دائماً بالجداول الزمنية للمشاريع التجارية في البحرين مع توثيق ضريبي شفاف وفريق حسابات سريع الاستجابة.', 5, true, 20, 2026, now() - interval '15 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.review (id, author_en, author_ar, company_en, company_ar, quote_en, quote_ar, rating, is_approved, sort_order, year, created_at) VALUES ('546fb225-29f6-4c2e-a1a7-f4d5cd0fe43b', 'Dr. Hessa Al-Zayani', 'د. حصة الزياني', 'Dilmunia Health & Wellness Center', 'مركز دلمونيا للصحة والعافية', 'From initial quotation to final commissioning, the Saffron Table operations team exceeded our SLA expectations.', 'من عرض السعر الأولي حتى التسليم النهائي، تجاوز فريق عمليات مائدة الزعفران توقعاتنا في الالتزام بمستوى الخدمة.', 5, true, 21, 2026, now() - interval '20 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('45324f5a-818d-4f07-a618-aecb4609570c', 'Are all Saffron Table invoices compliant with Bahrain NBR 10% VAT regulations?', 'هل جميع فواتير مائدة الزعفران متوافقة مع لوائح ضريبة القيمة المضافة 10% في البحرين؟', 'Yes. Every quotation and tax invoice includes our registered VAT ID (200015241000002), itemized tax calculations, and verifiable QR metadata.', 'نعم، تتضمن كل فاتورة ضريبية وعرض سعر رقمنا الضريبي المسجل (200015241000002) مع تفصيل الضريبة ورمز التحقق.', 'billing', true, 20, now() - interval '20 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.faq (id, question_en, question_ar, answer_en, answer_ar, category, is_published, sort_order, created_at) VALUES ('99b8ae61-942d-4630-aaf2-ca012dbc4ba1', 'Which Bahrain governorates and GCC destinations do you cover?', 'ما هي المحافظات في البحرين ووجهات الخليج التي تغطونها؟', 'We provide same-day and next-day fulfillment across Capital, Muharraq, Northern, and Southern Governorates, plus scheduled cross-border freight to Saudi Arabia, UAE, Qatar, Kuwait, and Oman.', 'نوفر التوصيل في نفس اليوم أو اليوم التالي في جميع محافظات البحرين، بالإضافة إلى الشحن المجدول لدول مجلس التعاون الخليجي.', 'logistics', true, 21, now() - interval '23 days') ON CONFLICT (id) DO NOTHING;
INSERT INTO cms.page (id, slug, page_type, title_en, title_ar, seo_title_en, seo_title_ar, seo_description_en, seo_description_ar, blocks, is_visible, in_header, in_footer, sort_order, created_at, updated_at) VALUES ('pg-home', 'home', 'home', 'Saffron Table', 'مائدة الزعفران', 'Saffron Table | Artisanal Gulf Kitchen, Pantry & Event Catering', 'مائدة الزعفران | مطبخ خليجي حرفي ومنتجات غذائية وضيافة مناسبات', 'Contemporary Bahraini kitchen and gourmet pantry crafting daily fresh dishes, specialty spice blends, and corporate catering. Explore Saffron Table in Adliya.', 'مطبخ بحريني معاصر ومتجر منتجات غذائية يقدم أطباقاً طازجة يومياً وخلطات توابل فاخرة وضيافة للشركات. تصفح صفحة مائدة الزعفران.', '[{"id":"pg-home-hero","type":"hero","titleEn":"Saffron Table | Artisanal Gulf Kitchen, Pantry & Event Catering","titleAr":"مائدة الزعفران | مطبخ خليجي حرفي ومنتجات غذائية وضيافة مناسبات","image":"/api/files/media/banners/banner-01.png"},{"id":"pg-home-body","type":"rich_section","ctaEn":"Request Proposal","ctaAr":"طلب عرض سعر","sortOrder":1}]'::jsonb, true, true, false, 1, now() - interval '2160 hours', now()) ON CONFLICT (id) DO NOTHING;
